function downloadBase64File(r){const bytes=Uint8Array.from(atob(r.base64),c=>c.charCodeAt(0));const blob=new Blob([bytes],{type:r.mimeType});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=r.fileName;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function renderCash(){
  heading('Kasa / Banka','Gelirler, personel ve öğretmen ödemeleri, cari ödemeler ve fiş giderlerinin net bakiyesi');
  const admin=state.data.user.role==='YÖNETİCİ';
  const cash=state.data.cash||{accounts:[],totalBalance:0,totalCollected:0};
  const activeAccounts=(cash.accounts||[]).filter(x=>x.active);
  const balanceByTypes=types=>activeAccounts.filter(x=>types.includes(String(x.type||'').toUpperCase())).reduce((sum,x)=>sum+(Number(x.balance)||0),0);
  const fxAccounts=activeAccounts.filter(x=>String(x.type||'').toUpperCase()==='DÖVİZ');const fxNative=fxAccounts.reduce((sum,x)=>sum+(Number(x.foreignBalance)||0),0);
  const cashBalances=[['Nakit mevcudu',money(balanceByTypes(['KASA']))],['Banka mevcudu',money(balanceByTypes(['BANKA','POS']))],['Döviz mevcudu',`${currencyQuantity(fxNative,'USD')}<small>${money(balanceByTypes(['DÖVİZ']))} TL karşılığı</small>`],['Çek mevcudu',money(balanceByTypes(['ÇEK']))],['Altın mevcudu',money(balanceByTypes(['ALTIN']))],['Net kasa / banka',money(cash.totalBalance)]];
  const rows=[...cash.accounts].sort((a,b)=>b.balance-a.balance).map(x=>{const fx=String(x.type||'').toUpperCase()==='DÖVİZ';return `<tr><td><button class="table-link" onclick="cashStatementModal('${esc(x.id)}')">${esc(x.name)}</button></td><td>${esc(x.type)}</td><td class="money">${fx?`${currencyQuantity(x.openingForeign,x.currency)}<small>${money(x.openingBalance)} TL karşılığı</small>`:money(x.openingBalance)}</td><td class="money income-cell">${fx?`${currencyQuantity(x.foreignCollected,x.currency)}<small>${money(x.collected)} TL karşılığı</small>`:money(x.collected)}</td><td class="money finance-cell">${money(x.borrowed)}</td><td class="money expense-cell">${money(x.staffExpense)}</td><td class="money expense-cell">${money(x.teacherExpense)}</td><td class="money expense-cell">${money(x.currentExpense)}</td><td class="money expense-cell">${money(x.receiptExpense)}</td><td class="money expense-cell">${money(x.debtRepaid)}</td><td class="money">${fx?`${currencyQuantity(x.foreignBalance,x.currency)}<small>${money(x.balance)} TL karşılığı</small>`:money(x.balance)}</td><td><span class="status ${x.active?'green':'red'}">${x.active?'Aktif':'Pasif'}</span></td>${admin?`<td><div class="row-actions"><button class="btn tiny" onclick="editCashAccountModal('${esc(x.id)}')">Düzelt</button><button class="btn tiny ${x.active?'danger':'secondary'}" onclick="toggleCashAccount('${esc(x.id)}',${!x.active})">${x.active?'Pasif':'Aktif'}</button></div></td>`:''}</tr>`});
  const headers=['Hesap','Tür','Açılış','Tahsilat','Borç Alımı','Personel','Öğretmen','Cari','Fiş','Borç Ödeme','Net Bakiye','Durum'];if(admin)headers.push('İşlem');
  const actions=`<div class="actions"><button class="btn secondary" onclick="cashStatementModal()">Tüm kasa ekstresi</button>${admin?'<button class="btn secondary" onclick="runSystemMaintenance()">Bakiyeleri doğrula</button><button class="btn primary" onclick="cashAccountModal()">Yeni hesap</button>':''}</div>`;
  $('#content').innerHTML=cards(cashBalances)+cards([['Tahsilat geliri',money(cash.totalCollected)],['Borç girişi',money(cash.totalBorrowed)],['Toplam çıkış',money(cash.totalExpense)]])+panel('Gelir - gider ve finansman hesapları',`<div class="upload-note cash-summary-note"><strong>Kasa özeti yalnızca aktif hesapları içerir.</strong><span>Pasif hesaplar ve geçmiş hareketleri aşağıdaki listede korunur ancak mevcut ve net toplamları etkilemez.</span></div>${table(headers,rows)}`,actions);
}
function cashAccountModal(){
  const fields=inputField('Hesap adı','fCashName','text',false,'required')+selectField('Hesap türü','fCashType',['KASA','BANKA','POS','DÖVİZ','ÇEK','ALTIN','DİĞER'])+inputField('Açılış TL bakiyesi','fCashOpening','number',false,'min="0" step="0.01" value="0" required')+cashFxAccountFields()+inputField('Açıklama','fCashNote','text',true);
  showModal('Yeni kasa / banka hesabı',formHtml(fields,'submitCashAccount()'));
  bindCashAccountType();
}
function cashFxAccountFields(x={}){const legacy=String(x.type||'').toUpperCase()==='DÖVİZ'&&!(Number(x.openingForeign)>0)&&!(Number(x.openingRate)>0)&&(Number(x.openingBalance)>0);const foreign=legacy?Number(x.openingBalance):(Number(x.openingForeign)||0);return `<div id="cashFxFields" class="wide fx-fields hidden"><div class="fx-grid">${inputField('Para birimi','fCashCurrency','text',false,`value="${esc(x.currency||'USD')}" readonly`)}${inputField('Dolar mevcudu','fCashForeign','number',false,`min="0" step="0.01" value="${foreign}" oninput="updateCashOpeningTl()" required`)}${inputField('1 USD kuru (TL)','fCashRate','number',false,`min="0.0001" step="0.0001" value="${Number(x.openingRate)||0}" oninput="updateCashOpeningTl()" required`)}</div><div id="cashFxPreview" class="fx-calculation"></div>${legacy?'<div class="modal-warning-note">Bu hesap eski kayıt biçimindeydi. Dolar mevcudu mevcut değerden getirildi; güncel kuru yazıp kaydettiğinizde TL karşılığı doğru biçimde oluşturulur.</div>':''}<div class="fx-note">Dolar mevcudu ana bakiyedir. TL karşılığı, dolar × girilen kur ile otomatik hesaplanır.</div></div>`}
function bindCashAccountType(){const type=$('#fCashType');if(!type)return;type.onchange=toggleCashAccountFx;toggleCashAccountFx()}
function toggleCashAccountFx(){const fx=$('#fCashType')?.value==='DÖVİZ';$('#cashFxFields')?.classList.toggle('hidden',!fx);if($('#fCashOpening'))$('#fCashOpening').readOnly=fx;if(fx)updateCashOpeningTl()}
function updateCashOpeningTl(){const foreign=Number($('#fCashForeign')?.value)||0;const rate=Number($('#fCashRate')?.value)||0;const tl=Math.round(foreign*rate*100)/100;if($('#fCashOpening'))$('#fCashOpening').value=tl.toFixed(2);if($('#cashFxPreview'))$('#cashFxPreview').innerHTML=`<span>Dolar mevcudu <strong>${currencyQuantity(foreign,'USD')}</strong></span><span>TL karşılığı <strong>${money(tl)}</strong></span>`}
function cashAccountPayload(){return {name:$('#fCashName').value,type:$('#fCashType').value,openingBalance:$('#fCashOpening').value,currency:$('#fCashCurrency')?.value||'',openingForeign:$('#fCashForeign')?.value||0,openingRate:$('#fCashRate')?.value||0,note:$('#fCashNote').value}}
async function submitCashAccount(){const required=['fCashName','fCashType'];if($('#fCashType')?.value==='DÖVİZ')required.push('fCashForeign','fCashRate');if(!validateModalFields(required))return;await submit('saveCashAccount',cashAccountPayload())}
function editCashAccountModal(id){const x=(state.data.cash?.accounts||[]).find(r=>r.id===id);if(!x)return;showModal('Kasa / banka hesabını düzelt',formHtml(inputField('Hesap adı','fCashName','text',false,`value="${esc(x.name)}" required`)+selectField('Hesap türü','fCashType',['KASA','BANKA','POS','DÖVİZ','ÇEK','ALTIN','DİĞER'])+inputField('Açılış TL bakiyesi','fCashOpening','number',false,`min="0" step="0.01" value="${x.openingBalance}" required`)+cashFxAccountFields(x)+inputField('Açıklama','fCashNote','text',true,`value="${esc(x.note||'')}"`),`submitCashAccountEdit('${esc(id)}')`));$('#fCashType').value=x.type;bindCashAccountType()}
async function submitCashAccountEdit(id){const required=['fCashName','fCashType'];if($('#fCashType')?.value==='DÖVİZ')required.push('fCashForeign','fCashRate');if(!validateModalFields(required))return;await submit('updateCashAccount',Object.assign({id:id},cashAccountPayload()))}
async function runSystemMaintenance(){if(!confirm('Taahhüt, tahakkuk, cari ve borç bakiyeleri hareketlerden yeniden hesaplansın mı?'))return;setBusy(true);try{const r=await server('reconcileSystem',state.token);const c=r.counts;alert(`Doğrulama tamamlandı.\nTaahhüt: ${c.pledges}\nPersonel tahakkuku: ${c.staff}\nÖğretmen tahakkuku: ${c.teachers}\nCari gider: ${c.currentExpenses||0}\nBorç: ${c.loans}`+(r.negativeAccounts.length?'\n\nDikkat: Eksi hesaplar: '+r.negativeAccounts.map(x=>x.name+' '+money(x.balance)).join(', '):'\n\nEksi hesap bulunmadı.'));scheduleDataSync()}catch(e){toast(e.message,true)}finally{setBusy(false)}}
async function toggleCashAccount(id,active){if(!active&&!confirm('Bu hesap yeni tahsilat girişlerine kapatılsın mı? Mevcut bakiye korunur.'))return;await submit('setCashAccountActive',id,active)}
function cashStatementModal(accountId=''){
  const accounts=(state.data.cash?.accounts||[]).map(x=>({value:x.id,label:x.name+(x.active?'':' · Pasif')}));
  const options=[{value:'',label:'Tüm hesaplar'},...accounts];
  const accountSelect=selectValueField('Hesap','cashStatementAccount',options).replace('id="cashStatementAccount"','id="cashStatementAccount" onchange="renderCashStatement()"');
  const controls=`<div id="cashStatementHero"></div><section class="statement-filter-card"><div class="statement-controls">${accountSelect}${inputField('Başlangıç','cashStatementStart','date',false,'onchange="renderCashStatement()"')}${inputField('Bitiş','cashStatementEnd','date',false,'onchange="renderCashStatement()"')}<button class="btn primary statement-show-btn" type="button" onclick="renderCashStatement()">Ekstreyi göster</button></div><div class="statement-filter-footer"><div class="statement-periods" role="group" aria-label="Hızlı tarih aralığı"><button class="statement-period-btn active" type="button" onclick="setCashStatementPeriod('all',this)">Tüm zamanlar</button><button class="statement-period-btn" type="button" onclick="setCashStatementPeriod('month',this)">Bu ay</button><button class="statement-period-btn" type="button" onclick="setCashStatementPeriod('30days',this)">Son 30 gün</button><button class="statement-period-btn" type="button" onclick="setCashStatementPeriod('year',this)">Bu yıl</button></div><button class="btn tiny secondary" type="button" onclick="printCashStatement()">Yazdır / PDF</button></div></section><div id="cashStatementResults" class="statement-results"></div>`;
  const selected=(state.data.cash?.accounts||[]).find(x=>x.id===accountId);
  showModal(selected?`${selected.name} · Hesap ekstresi`:'Tüm kasa / banka ekstresi',`<div class="statement-modal cash-statement-modal">${controls}</div>`);$('#modal').classList.add('wide-modal','statement-dialog');$('#cashStatementAccount').value=accountId;renderCashStatement();
}
function statementIsoDate(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function setCashStatementPeriod(period,button){
  const now=new Date();let start='';let end='';
  if(period!=='all'){end=statementIsoDate(now);const d=new Date(now);if(period==='month')d.setDate(1);else if(period==='year'){d.setMonth(0);d.setDate(1)}else if(period==='30days')d.setDate(d.getDate()-29);start=statementIsoDate(d)}
  if($('#cashStatementStart'))$('#cashStatementStart').value=start;if($('#cashStatementEnd'))$('#cashStatementEnd').value=end;
  document.querySelectorAll('.statement-period-btn').forEach(x=>x.classList.toggle('active',x===button));renderCashStatement();
}
function cashStatementHero(accountId){
  const cash=state.data.cash||{};const account=(cash.accounts||[]).find(x=>x.id===accountId);const all=!account;
  const title=all?'Tüm kasa ve banka hesapları':account.name;const type=all?'Konsolide ekstre':account.type;const balance=all?cash.totalBalance:account.balance;
  const status=all?'Yalnızca aktif hesapların net toplamı':(account.active?'Aktif hesap':'Pasif hesap · mevcut toplamları etkilemez');
  const fx=!all&&String(account.type||'').toUpperCase()==='DÖVİZ';
  return `<section class="statement-hero"><div class="statement-hero-main"><span class="statement-kicker">${all?'GENEL EKSTRE':'HESAP EKSTRESİ'}</span><strong>${esc(title)}</strong><div class="statement-hero-meta"><span>${esc(type)}</span><span class="status ${all||account.active?'green':'red'}">${esc(status)}</span></div></div><div class="statement-hero-balance"><span>Güncel bakiye</span><strong>${fx?currencyQuantity(account.foreignBalance,account.currency):money(balance)}</strong>${fx?`<small>${money(balance)} TL karşılığı</small>`:''}</div></section>`;
}
function renderCashStatement(){
  const accountId=$('#cashStatementAccount')?.value||'';const start=$('#cashStatementStart')?.value||'';const end=$('#cashStatementEnd')?.value||'';if(start&&end&&start>end){toast('Başlangıç tarihi bitiş tarihinden sonra olamaz.',true);return}
  const all=(state.data.cash?.movements||[]).filter(x=>accountId?x.accountId===accountId:x.active===true);const opening=all.filter(x=>start&&String(x.date||'')<start).reduce((sum,x)=>sum+(Number(x.income)||0)-(Number(x.expense)||0),0);const period=all.filter(x=>(!start||String(x.date||'')>=start)&&(!end||String(x.date||'')<=end));let running=opening;const withBalance=[...period].sort((a,b)=>String(a.date).localeCompare(String(b.date))||String(a.id).localeCompare(String(b.id))).map(x=>{running+=Number(x.income)||0;running-=Number(x.expense)||0;return {x:x,balance:running}}).reverse();const income=period.reduce((s,x)=>s+(Number(x.income)||0),0);const expense=period.reduce((s,x)=>s+(Number(x.expense)||0),0);const rows=withBalance.map(({x,balance})=>`<tr><td>${date(x.date)}</td><td>${esc(x.accountName)}</td><td><span class="movement-type ${x.income?'in':'out'}">${esc(x.type)}</span></td><td class="statement-description">${esc(x.description)||'—'}</td><td class="money income-cell">${x.income?money(x.income):'—'}${x.foreignAmount?`<small>${foreignMoney(x.foreignAmount,x.currency)} × ${Number(x.exchangeRate).toLocaleString('tr-TR')}</small>`:''}</td><td class="money expense-cell">${x.expense?money(x.expense):'—'}</td><td class="money statement-balance">${money(balance)}</td></tr>`);
  const range=start||end?`${start?date(start):'İlk kayıt'} – ${end?date(end):'Bugün'}`:'Tüm zamanlar';const summary=`<div class="statement-summary"><div class="statement-metric"><span>Dönem başı</span><strong>${money(opening)}</strong></div><div class="statement-metric income"><span>Toplam giriş</span><strong>${money(income)}</strong></div><div class="statement-metric expense"><span>Toplam çıkış</span><strong>${money(expense)}</strong></div><div class="statement-metric closing"><span>Dönem sonu</span><strong>${money(opening+income-expense)}</strong></div></div>`;
  if($('#cashStatementHero'))$('#cashStatementHero').innerHTML=cashStatementHero(accountId);
  $('#cashStatementResults').innerHTML=`<div class="statement-results-head"><div><strong>Hesap hareketleri</strong><span>${esc(range)} · ${period.length} hareket</span></div></div>${summary}<div class="statement-ledger">${table(['Tarih','Hesap','Hareket','Açıklama','Giriş','Çıkış',accountId?'Bakiye':'Toplam Bakiye'],rows,'Seçilen tarih aralığında hareket bulunamadı.')}</div>`;
}
function printCashStatement(){
  const accountId=$('#cashStatementAccount')?.value||'';const account=(state.data.cash?.accounts||[]).find(x=>x.id===accountId);const title=account?account.name+' Hesap Ekstresi':'Tüm Kasa / Banka Ekstresi';const results=$('#cashStatementResults')?.innerHTML||'';if(!results){toast('Yazdırılacak ekstre bulunamadı.',true);return}
  const w=window.open('','_blank','width=1200,height=850');if(!w){toast('Yazdırma penceresi açılamadı. Tarayıcı açılır pencere iznini kontrol edin.',true);return}const printStart=$('#cashStatementStart')?.value?date($('#cashStatementStart').value):'İlk kayıt';const printEnd=$('#cashStatementEnd')?.value?date($('#cashStatementEnd').value):'Bugün';w.document.write(`<!doctype html><html lang="tr"><head><meta charset="utf-8"><title>${esc(title)}</title><style>body{font-family:Arial,sans-serif;color:#102a43;padding:28px}h1{margin:0 0 6px}p{margin:0 0 20px;color:#687889}.statement-results-head{margin:18px 0 10px}.statement-results-head span{display:block;color:#687889;font-size:12px}.statement-summary{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:16px}.statement-metric{border:1px solid #dce3e9;border-radius:10px;padding:12px}.statement-metric span{display:block;color:#687889;font-size:12px}.statement-metric strong{display:block;margin-top:5px}.table-wrap{overflow:visible}.data-table{width:100%;border-collapse:collapse}.data-table th{background:#102a43;color:#fff;padding:8px;text-align:left;font-size:12px}.data-table td{border-bottom:1px solid #dce3e9;padding:8px;font-size:12px}.money{text-align:right}.movement-type{font-weight:700}.income-cell{color:#14804a}.expense-cell{color:#b42318}@media print{body{padding:0}}</style></head><body><h1>${esc(title)}</h1><p>${printStart} – ${printEnd}</p>${results}</body></html>`);w.document.close();w.focus();setTimeout(()=>w.print(),250)
}

function renderGeneralExpenses(){
  heading('Giderler','Cari ödemeleri ve fiş giderlerini kasa / banka hesaplarıyla birlikte takip edin');
  const d=state.data.generalExpenses||{current:[],payments:[],receipts:[],currentTypes:[],receiptTypes:[],summary:{}};const s=d.summary||{};
  const tabs=`<div class="tabs"><button class="tab ${state.generalExpenseTab==='current'?'active':''}" onclick="setGeneralExpenseTab('current')">Cari Ödemeler</button><button class="tab ${state.generalExpenseTab==='receipts'?'active':''}" onclick="setGeneralExpenseTab('receipts')">Fiş Giderleri</button></div>`;
  let body='';let action='';
  if(state.generalExpenseTab==='current'){
    const paged=pageData('general-current',[...d.current].sort((a,b)=>String(b.year).localeCompare(String(a.year))||a.name.localeCompare(b.name,'tr')));
    const rows=paged.items.map(x=>`<tr><td>${esc(x.id)}</td><td>${esc(x.year)}</td><td>${esc(x.name)}</td><td>${esc(x.type)}</td><td class="money">${money(x.amount)}</td><td class="money">${money(x.paid)}</td><td class="money">${money(x.remaining)}</td><td><span class="status ${statusClass(x.status)}">${esc(x.status)}</span></td><td><div class="row-actions">${x.remaining>0?`<button class="btn tiny primary" onclick="currentExpensePaymentModal('${esc(x.id)}')">Ödeme yap</button>`:''}<button class="btn tiny" onclick="editCurrentExpenseModal('${esc(x.id)}')">Düzelt</button><button class="btn tiny danger" onclick="removeCurrentExpense('${esc(x.id)}')">Sil</button></div></td></tr>`);
    const paymentRows=[...d.payments].sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<tr><td>${esc(x.id)}</td><td>${date(x.date)}</td><td>${esc(x.currentId)}</td><td>${esc(x.name)}</td><td class="money">${money(x.amount)}</td><td>${esc(x.method)}</td><td>${esc(x.accountName)}</td><td><div class="row-actions"><button class="btn tiny" onclick="editCurrentExpensePaymentModal('${esc(x.id)}')">Düzelt</button><button class="btn tiny danger" onclick="removeCurrentExpensePayment('${esc(x.id)}')">Sil</button></div></td></tr>`);
    body=table(['Cari No','Cari Yılı','Cari Adı','Nevi','Tutar','Ödenen','Kalan','Durum','İşlem'],rows,'Henüz cari gider kaydı yok.')+paged.controls+panel('Cari ödeme hareketleri',table(['Hareket No','Tarih','Cari No','Cari Adı','Tutar','Ödeme Şekli','Kasa / Banka','İşlem'],paymentRows,'Henüz cari ödeme hareketi yok.'));
    action='<div class="actions"><button class="btn secondary" onclick="currentExpensePaymentModal()">Ödeme yap</button><button class="btn primary" onclick="currentExpenseModal()">Cari ekle</button></div>';
  }else{
    const paged=pageData('general-receipts',[...d.receipts].sort((a,b)=>b.date.localeCompare(a.date)));
    const rows=paged.items.map(x=>`<tr><td>${esc(x.id)}</td><td>${date(x.date)}</td><td>${esc(x.name)}</td><td>${esc(x.type)}</td><td class="money">${money(x.amount)}</td><td>${esc(x.method)}</td><td>${esc(x.accountName)}</td><td><div class="row-actions"><button class="btn tiny" onclick="editReceiptExpenseModal('${esc(x.id)}')">Düzelt</button><button class="btn tiny danger" onclick="removeReceiptExpense('${esc(x.id)}')">Sil</button></div></td></tr>`);
    body=table(['Gider No','Tarih','Gider Adı','Gider Türü','Miktarı','Ödeme Şekli','Kasa / Banka','İşlem'],rows,'Henüz fiş gideri yok.')+paged.controls;
    action='<button class="btn primary" onclick="receiptExpenseModal()">Fiş gideri ekle</button>';
  }
  $('#content').innerHTML=cards([['Cari toplamı',money(s.currentTotal)],['Cari ödenen',money(s.currentPaid)],['Cari kalan',money(s.currentRemaining)],['Fiş giderleri',money(s.receiptTotal)],['Toplam gider',money((Number(s.currentPaid)||0)+(Number(s.receiptTotal)||0))]])+panel('Gider kayıtları',tabs+body,action);
}
function setGeneralExpenseTab(tab){state.generalExpenseTab=tab;resetPage(tab==='current'?'general-current':'general-receipts');renderGeneralExpenses()}
function customTypeField(label,id,items,value=''){const list=id+'Options';return `<label>${esc(label)}<input id="${id}" list="${list}" value="${esc(value)}" autocomplete="off" placeholder="Seçin veya yeni tür yazın"><datalist id="${list}">${(items||[]).map(x=>`<option value="${esc(x)}"></option>`).join('')}</datalist></label>`}
function generalExpenseAccounts(selectedId=''){return (state.data.cash?.accounts||[]).filter(x=>(x.active||x.id===selectedId)&&['KASA','BANKA'].includes(String(x.type).toUpperCase())).map(x=>({value:x.id,label:x.name+' · '+money(x.balance)}))}
function ensureGeneralExpenseAccount(selectedId=''){const accounts=generalExpenseAccounts(selectedId);if(!accounts.length){toast('Ödeme için aktif Nakit Kasa veya Banka hesabı oluşturun.',true);return null}return accounts}
function currentExpenseFields(x={}){const d=state.data.generalExpenses||{};return inputField('Cari yılı','fCurrentYear','number',false,`min="1900" max="2100" value="${esc(x.year||new Date().getFullYear())}"`)+inputField('Cari adı','fCurrentName','text',false,`value="${esc(x.name||'')}"`)+customTypeField('Nevi','fCurrentType',d.currentTypes||[],x.type||'')+inputField('Tutar','fCurrentAmount','number',false,`min="0.01" step="0.01" value="${x.amount||''}"`)+inputField('Açıklama','fCurrentNote','text',true,`value="${esc(x.note||'')}"`)}
function currentExpenseModal(){showModal('Cari gider ekle',formHtml(currentExpenseFields(),'submitCurrentExpense()'))}
function editCurrentExpenseModal(id){const x=(state.data.generalExpenses?.current||[]).find(r=>r.id===id);if(!x)return;showModal('Cari gideri düzelt',formHtml(currentExpenseFields(x),`submitCurrentExpenseEdit('${esc(id)}')`))}
function currentExpensePayload(id=''){return {id:id,year:$('#fCurrentYear').value,name:$('#fCurrentName').value,type:$('#fCurrentType').value,amount:$('#fCurrentAmount').value,note:$('#fCurrentNote').value}}
async function submitCurrentExpense(){await submit('saveCurrentExpense',currentExpensePayload())}
async function submitCurrentExpenseEdit(id){await submit('updateCurrentExpense',currentExpensePayload(id))}
async function removeCurrentExpense(id){if(!confirm('Bu cari gider kaydı silinsin mi? Bağlı ödeme varsa önce ödeme hareketlerini silmeniz gerekir.'))return;await submit('deleteCurrentExpense',id)}
function currentExpensePaymentModal(preselectedId=''){
  const open=(state.data.generalExpenses?.current||[]).filter(x=>x.remaining>0);const selected=open.find(x=>x.id===preselectedId);if(!open.length){toast('Ödenecek açık cari kaydı bulunmuyor.',true);return}const accounts=ensureGeneralExpenseAccount();if(!accounts)return;
  const picker=selected?`<div class="wide selected-pledge-summary"><strong>${esc(selected.name)}</strong><span>${esc(selected.type)} · Kalan: ${money(selected.remaining)}</span><input id="currentExpensePickerSelected" type="hidden" value="${esc(selected.id)}"></div>`:searchPickerHtml('currentExpensePicker',open,x=>`<strong>${esc(x.name)}</strong><span>${esc(x.year)} · ${esc(x.type)} · Kalan: ${money(x.remaining)}</span>`);
  showModal('Cari ödeme yap',formHtml(picker+inputField('Ödeme tutarı','fCurrentPaymentAmount','number',false,'min="0.01" step="0.01"')+inputField('Ödeme tarihi','fCurrentPaymentDate','date',false,`value="${new Date().toISOString().slice(0,10)}"`)+selectValueField('Ödeme hesabı','fCurrentPaymentAccount',accounts)+inputField('Açıklama','fCurrentPaymentNote','text',true),'submitCurrentExpensePayment()'));
}
