function toggleCollectionFxFields(){const fx=String(selectedCollectionAccount()?.type||'').toUpperCase()==='DÖVİZ';$('#collectionFxFields')?.classList.toggle('hidden',!fx);if($('#fAmount'))$('#fAmount').readOnly=fx;if(fx){if($('#fCurrency'))$('#fCurrency').value=selectedCollectionAccount()?.currency||'USD';updateCollectionTlAmount()}}
